import axios from "axios";

const API = axios.create({
  baseURL: "http://localhost:5000/api"
});

export const uploadMeeting = (formData) =>
  API.post("/upload", formData);

export const processTranscript = (transcript) =>
  API.post("/ai/process", { transcript });

export const startLiveBot = (meetingLink) =>
  API.post("/live/start", { meetingLink });

export const downloadPDF = (data) =>
  API.post("/pdf/download", data, { responseType: "blob" });
